<script>
window.LabKit = window.LabKit || (() => {
  const NS = 'http://www.w3.org/2000/svg';
  const sum = a => a.reduce((s, v) => s + v, 0);
  const mean = a => sum(a) / a.length;
  const variance = (a, ddof = 0) => { const m = mean(a); return sum(a.map(v => (v - m) ** 2)) / (a.length - ddof); };
  const sd = (a, ddof = 0) => Math.sqrt(variance(a, ddof));
  // Percentil con interpolación lineal (convención de numpy.percentile por defecto).
  const quantile = (a, q) => {
    const s = [...a].sort((x, y) => x - y), pos = (s.length - 1) * q, lo = Math.floor(pos), hi = Math.ceil(pos);
    return s[lo] + (s[hi] - s[lo]) * (pos - lo);
  };
  const median = a => quantile(a, 0.5);
  const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
  const fmt = (v, d = 2) => (v === null || v === undefined || Number.isNaN(v)) ? '—'
    : Number(v).toLocaleString('es-MX', { minimumFractionDigits: d, maximumFractionDigits: d });
  // Generador pseudoaleatorio reproducible (mulberry32) y normal estándar (Box-Muller).
  const rng = seed => {
    let t = seed >>> 0;
    const u = () => { t += 0x6D2B79F5; let r = Math.imul(t ^ (t >>> 15), 1 | t); r ^= r + Math.imul(r ^ (r >>> 7), 61 | r); return ((r ^ (r >>> 14)) >>> 0) / 4294967296; };
    u.normal = () => { let a = 0, b = 0; while (a === 0) a = u(); while (b === 0) b = u(); return Math.sqrt(-2 * Math.log(a)) * Math.cos(2 * Math.PI * b); };
    return u;
  };
  const niceTicks = (lo, hi, n = 5) => {
    if (hi === lo) { hi = lo + 1; }
    const raw = (hi - lo) / n, mag = 10 ** Math.floor(Math.log10(raw)), f = raw / mag;
    const step = (f >= 5 ? 10 : f >= 2 ? 5 : f >= 1 ? 2 : 1) * mag;
    const out = [];
    for (let v = Math.ceil(lo / step - 1e-9) * step; v <= hi + 1e-9; v += step) out.push(Math.abs(v) < step * 1e-9 ? 0 : v);
    return out;
  };
  const el = (tag, attrs = {}, parent) => {
    const node = document.createElementNS(NS, tag);
    for (const [k, v] of Object.entries(attrs)) if (v !== undefined && v !== null) node.setAttribute(k, v);
    if (parent) parent.appendChild(node);
    return node;
  };
  // Graficador mínimo: escala lineal, ejes, rejilla y primitivas.
  function chart(svg, opts) {
    const W = opts.width || 480, H = opts.height || 300;
    const m = Object.assign({ top: 14, right: 14, bottom: 38, left: 48 }, opts.margin || {});
    svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
    svg.classList.add('plab-chart');
    svg.replaceChildren();
    const [x0, x1] = opts.x, [y0, y1] = opts.y;
    const iw = W - m.left - m.right, ih = H - m.top - m.bottom;
    const X = v => m.left + (v - x0) / (x1 - x0) * iw;
    const Y = v => m.top + ih - (v - y0) / (y1 - y0) * ih;
    const c = {
      svg, X, Y, W, H, m, iw, ih,
      invX: px => x0 + (px - m.left) / iw * (x1 - x0),
      invY: py => y0 + (m.top + ih - py) / ih * (y1 - y0),
      g: el('g', {}, svg),
      axes({ xTicks = 5, yTicks = 5, xLabel = '', yLabel = '', xFmt = v => fmt(v, Math.abs(v) < 10 && v % 1 ? 1 : 0), yFmt, grid = true, xCats } = {}) {
        const ax = el('g', {}, svg); svg.insertBefore(ax, c.g);
        const yf = yFmt || xFmt;
        if (yTicks) niceTicks(y0, y1, yTicks).forEach(t => {
          if (grid) el('line', { x1: m.left, x2: m.left + iw, y1: Y(t), y2: Y(t), class: 'grid' }, ax);
          el('text', { x: m.left - 6, y: Y(t) + 3.5, 'text-anchor': 'end' }, ax).textContent = yf(t);
        });
        if (xCats) xCats.forEach(([v, lab]) => { el('text', { x: X(v), y: m.top + ih + 16, 'text-anchor': 'middle' }, ax).textContent = lab; });
        else if (xTicks) niceTicks(x0, x1, xTicks).forEach(t => {
          if (grid) el('line', { x1: X(t), x2: X(t), y1: m.top, y2: m.top + ih, class: 'grid' }, ax);
          el('text', { x: X(t), y: m.top + ih + 16, 'text-anchor': 'middle' }, ax).textContent = xFmt(t);
        });
        el('line', { x1: m.left, x2: m.left + iw, y1: m.top + ih, y2: m.top + ih, class: 'axis' }, ax);
        el('line', { x1: m.left, x2: m.left, y1: m.top, y2: m.top + ih, class: 'axis' }, ax);
        if (xLabel) el('text', { x: m.left + iw / 2, y: H - 4, 'text-anchor': 'middle', class: 'strong' }, ax).textContent = xLabel;
        if (yLabel) el('text', { x: 12, y: m.top + ih / 2, 'text-anchor': 'middle', transform: `rotate(-90 12 ${m.top + ih / 2})`, class: 'strong' }, ax).textContent = yLabel;
        return c;
      },
      zeroLines() {
        if (x0 < 0 && x1 > 0) el('line', { x1: X(0), x2: X(0), y1: m.top, y2: m.top + ih, class: 'zero' }, c.g);
        if (y0 < 0 && y1 > 0) el('line', { x1: m.left, x2: m.left + iw, y1: Y(0), y2: Y(0), class: 'zero' }, c.g);
        return c;
      },
      path(points, cls = 's1 line') {
        const d = points.filter(p => p && Number.isFinite(p[1])).map((p, i) => `${i ? 'L' : 'M'}${X(p[0]).toFixed(1)},${Y(p[1]).toFixed(1)}`).join('');
        return el('path', { d, class: cls }, c.g);
      },
      line(xa, ya, xb, yb, cls = 's1 line') { return el('line', { x1: X(xa), y1: Y(ya), x2: X(xb), y2: Y(yb), class: cls }, c.g); },
      dot(x, y, r = 5, cls = 's1 dot') { return el('circle', { cx: X(x), cy: Y(y), r, class: cls }, c.g); },
      rect(xa, ya, xb, yb, cls = 's1 soft') {
        return el('rect', { x: Math.min(X(xa), X(xb)), y: Math.min(Y(ya), Y(yb)), width: Math.abs(X(xb) - X(xa)), height: Math.abs(Y(yb) - Y(ya)), class: cls }, c.g);
      },
      text(x, y, s, attrs = {}) { const t = el('text', Object.assign({ x: X(x), y: Y(y) }, attrs), c.g); t.textContent = s; return t; },
      arrow(xa, ya, xb, yb, cls = 's1') {
        const ax = X(xa), ay = Y(ya), bx = X(xb), by = Y(yb), ang = Math.atan2(by - ay, bx - ax), h = 8;
        el('line', { x1: ax, y1: ay, x2: bx, y2: by, class: cls + ' line' }, c.g);
        el('path', { d: `M${bx},${by}L${bx - h * Math.cos(ang - 0.4)},${by - h * Math.sin(ang - 0.4)}L${bx - h * Math.cos(ang + 0.4)},${by - h * Math.sin(ang + 0.4)}Z`, class: cls }, c.g);
      },
      // Convierte un evento de puntero a coordenadas de datos.
      pointer(evt) {
        const pt = svg.createSVGPoint(); pt.x = evt.clientX; pt.y = evt.clientY;
        const p = pt.matrixTransform(svg.getScreenCTM().inverse());
        return [c.invX(p.x), c.invY(p.y)];
      }
    };
    svg.__chart = c;
    return c;
  }
  // Botones segmentados: devuelve un getter del valor activo.
  function segmented(container, onChange) {
    const buttons = [...container.querySelectorAll('button')];
    let value = (buttons.find(b => b.getAttribute('aria-pressed') === 'true') || buttons[0]).dataset.value;
    const set = v => { value = v; buttons.forEach(b => b.setAttribute('aria-pressed', String(b.dataset.value === v))); };
    set(value);
    buttons.forEach(b => b.addEventListener('click', () => { set(b.dataset.value); onChange && onChange(value); }));
    return { get: () => value, set: v => { set(v); onChange && onChange(value); } };
  }
  return { sum, mean, variance, sd, quantile, median, clamp, fmt, rng, niceTicks, el, chart, segmented };
})();
</script>
```
:::



En el capitulo anterior construimos redes neuronales desde cero con NumPy: derivamos la regla de la cadena a mano, escribimos cada operación de convolución a mano y controlamos cada actualización de pesos. Ese ejercicio es indispensable para entender *por qué* funcionan los algoritmos.

Este capitulo es el complemento práctico. Tomamos exactamente los mismos conceptos — forward pass, backprop, descenso por gradiente — y los reimplementamos en frameworks de producción que automatizan lo que ya entendemos.

Hay tres alternativas principales según el nivel de abstracción:

- **scikit-learn** — Un `MLPClassifier` con la interfaz `fit/predict` de siempre. Ideal para tablas pequeñas; sin control sobre el ciclo de entrenamiento.
- **PyTorch** [@paszke2019pytorch] — Grafos computacionales dinámicos, diferenciación automática y una API orientada a objetos. El estándar de facto en investigación académica.
- **JAX** [@bradbury2018jax] — Paradigma funcional puro: funciones sin estado, PRNG explícito, compilación XLA transparente. Sobre JAX se construye Flax [@heek2023flax] (módulos de redes) y Optax [@deepmind2020optax] (optimizadores).

La diferencia entre PyTorch y JAX no es solo sintáctica: reflejan dos paradigmas de programación opuestos. PyTorch es **imperativo** — escribes instrucciones sobre objetos con estado. JAX es **funcional** — las funciones no tienen estado y se pueden transformar automáticamente. Comprender esta diferencia es el objetivo central de este capítulo.

## El ecosistema de aprendizaje profundo {#sec-ecosistema}

### scikit-learn: MLPClassifier {#sec-sklearn}

Scikit-learn [@pedregosa2011] incluye `sklearn.neural_network.MLPClassifier`, un perceptrón multicapa que se integra sin fricciones en cualquier pipeline de sklearn. Acepta los mismos hiperparámetros conceptuales que ya conocemos: número y tamaño de capas ocultas (`hidden_layer_sizes`), función de activación, optimizador (lbfgs, sgd o adam) y tasa de aprendizaje. La interfaz es idéntica a la de cualquier otro clasificador de sklearn: `fit` para entrenar, `predict` para inferencia y `score` para exactitud. Esta uniformidad hace que sea trivial sustituirlo por un árbol de decisión o una SVM en un experimento comparativo.

Las limitaciones son igualmente claras. No permite definir arquitecturas personalizadas: capas convolucionales, mecanismos de atención, conexiones residuales o cualquier topología no secuencial están fuera de alcance. El entrenamiento ocurre en CPU y no escala a conjuntos de datos de imagen o texto de tamaño real. La ausencia de control sobre el ciclo de entrenamiento impide aplicar técnicas avanzadas como curriculum learning, ciclos de tasa de aprendizaje o pérdidas compuestas. Para todo esto se requieren frameworks de bajo nivel.

```python
from sklearn.neural_network import MLPClassifier
from sklearn.datasets import make_moons
import numpy as np

X, y = make_moons(n_samples=400, noise=0.2, random_state=42)
clf = MLPClassifier(hidden_layer_sizes=(16, 16), max_iter=500, random_state=42)
clf.fit(X, y)
print(f"Accuracy: {clf.score(X, y):.3f}")
```

### PyTorch {#sec-pytorch-intro}

PyTorch [@paszke2019pytorch] introdujo en 2017 el **grafo computacional dinámico** (*define-by-run*): el grafo se construye al vuelo mientras se ejecutan operaciones sobre tensores, no antes. A diferencia del grafo estático de TensorFlow 1.x, el código de PyTorch es Python normal — se puede depurar con `print` y `pdb`, y las estructuras de control funcionan exactamente como se esperaría.

El motor de diferenciación automática se llama **Autograd**. Cuando un tensor tiene `requires_grad=True`, cada operación sobre él registra un nodo en el grafo. Al llamar `.backward()` sobre la pérdida escalar, Autograd recorre el grafo en sentido inverso y acumula los gradientes en el atributo `.grad` de cada parámetro.

La clase base para todo modelo es `nn.Module`. Su contrato: el constructor `__init__` declara las capas, y el método `forward` describe el cómputo. El ciclo de entrenamiento es explícito — el programador escribe cada paso. Esa explicitación es una característica, no un defecto: da control total.

### JAX {#sec-jax-intro}

JAX [@bradbury2018jax] parte de una premisa diferente: las **transformaciones funcionales** son ciudadanos de primera clase. El núcleo son cuatro transformaciones componibles:

| Transformación | Qué hace |
|---|---|
| `jax.grad(f)` | Diferenciación automática de funciones escalares |
| `jax.jit(f)` | Compilación XLA transparente |
| `jax.vmap(f)` | Vectorización sobre dimensiones de lote |
| `jax.pmap(f)` | Paralelismo en múltiples dispositivos |

Para beneficiarse de `jax.jit`, las funciones deben ser **puras**: sin efectos secundarios, sin estado global mutable. Los pesos del modelo se pasan como *pytrees* (diccionarios/listas de arrays JAX) que JAX recorre automáticamente.

Flax [@heek2023flax] añade una API de módulos similar a `nn.Module`, manteniendo la disciplina funcional: `model.init(key, x)` devuelve los parámetros y `model.apply(params, x)` ejecuta el forward pass sin modificar nada internamente. Optax [@deepmind2020optax] provee los optimizadores.

### Comparativa de frameworks {#sec-comparativa-ecosistema}

La elección entre frameworks depende del caso de uso. Para prototipado rápido con datos tabulares, sklearn es imbatible en simplicidad. Para investigación en arquitecturas novedosas o fine-tuning de modelos preentrenados del ecosistema HuggingFace, PyTorch es el estándar de facto. Para investigación que requiere transformaciones funcionales, diferenciación de orden superior o integración nativa con TPUs de Google, JAX es la opción más poderosa. El siguiente radar resume estas características de forma comparativa.

